"""Local compat shim: run this old matplotlib tree against the venv's numpy 2.x.

numpy 2 removed a handful of aliases that matplotlib 3.6 still uses.
Loaded automatically (sitecustomize) whenever Python runs with this
directory on sys.path (e.g. pytest from the repo root).  Everything is
guarded so it is a no-op under numpy 1.x.
"""
try:
    import numpy as _np
except ImportError:  # pragma: no cover
    _np = None

if _np is not None:
    if not hasattr(_np, "row_stack"):
        _np.row_stack = _np.vstack
    if not hasattr(_np, "Inf"):
        _np.Inf = _np.inf
    if not hasattr(_np, "NaN"):
        _np.NaN = _np.nan
    if not hasattr(_np, "infty"):
        _np.infty = _np.inf
    if not hasattr(_np, "float_"):
        _np.float_ = _np.float64
    if not hasattr(_np, "unicode_"):
        _np.unicode_ = _np.str_
    if not hasattr(_np, "string_"):
        _np.string_ = _np.bytes_
    if not hasattr(_np, "bool8"):
        _np.bool8 = _np.bool_
    if not hasattr(_np, "alltrue"):
        _np.alltrue = _np.all
    if not hasattr(_np, "sometrue"):
        _np.sometrue = _np.any
    if not hasattr(_np, "product"):
        _np.product = _np.prod
    if not hasattr(_np, "round_"):
        _np.round_ = _np.round
    if not hasattr(_np, "msort"):
        _np.msort = lambda a: _np.sort(a, axis=0)

